def add(n,kind,pack,scans,lines,words,statement,reconstruction,check,reason,src):
    item={'id':f'SA14-{n}','sources':[], 'kind':kind,'cote':57,'scans':scans,'lines':f'SA14_texts/pro/{pack}_transcription.tex:{lines}','his_words':words,'statement':statement,'reconstruction':reconstruction,'check':check,'check_reason':reason}
    for package,num,verdict,why in src:
        eid=f'{package}#{num}';item['sources'].append(eid)
        entries.append({'entry_id':eid,'item_id':item['id'],'verdict':verdict,'reason':why})
    items.append(item)
